mapper.select:
SELECT f.id, f.user_id, f.target_type, f.target_id, f.create_time, CASE WHEN f.target_type = 'lab' THEN lr.name WHEN f.target_type = 'device' THEN d.device_name END AS target_name, CASE WHEN f.target_type = 'lab' THEN lr.image_url WHEN f.target_type = 'device' THEN d.image_url END AS target_image, CASE WHEN f.target_type = 'lab' THEN lr.location WHEN f.target_type = 'device' THEN d.model END AS target_sub FROM favorite f LEFT JOIN lab_room lr ON f.target_type = 'lab' AND f.target_id = lr.id LEFT JOIN device d ON f.target_type = 'device' AND f.target_id = d.id WHERE f.user_id = #{userId}
AND f.target_type = #{targetType}
ORDER BY f.create_time DESC
